hero_ids_with_death_touch = set()
with open('csv/hero_power.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['power_id'] == '37':
            hero_ids_with_death_touch.add(row['hero_id'])

print(f"Found {len(hero_ids_with_death_touch)} heroes with Death Touch power")

# Read superhero.csv to get superhero_name for these hero_ids
hero_names = []
with open('csv/superhero.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['id'] in hero_ids_with_death_touch:
            if row['superhero_name']:
                hero_names.append(row['superhero_name'])

print(f"Found {len(hero_names)} superhero names")
for name in sorted(hero_names):
